Section CANSEC1. Context {rc : runConstT}.

Section L2SA.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (m0 : amem) (DT WK T nbb maxW minB scl st sym1 cons minW : Z) (sorted : list (option Z)) (js jt : list byte)
    (ncells : nat) (rs0 rv : list Z).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (4 * ncells)%nat.
  Hypothesis HJS : length js = length sorted.
  Hypothesis HLS : length sorted = 256%nat.
  Hypothesis HSYR : forall i v, nth i sorted None = Some v -> 0 <= v < 256.
  Hypothesis PLC : x2placeA RNG m0 SPA DT WK js ncells.
  Hypothesis HS1 : 0 <= sym1 < 256.
  Hypothesis HT : 1 <= T <= 12.
  Hypothesis HNBB : 2 <= nbb <= 13.
  Hypothesis HWE : 2 <= maxW + 1 <= nbb.
  Hypothesis HCONS : 1 <= cons <= 11.
  Hypothesis HMW : 1 <= minW /\ cons + nbb - T <= minW.
  Hypothesis HST : 0 <= st.
  Hypothesis LRS : length rs0 = 15%nat.
  Hypothesis HRSV : forall w, 1 <= w <= maxW -> 0 <= Znth w rs0 <= Znth (w + 1) rs0 /\ Znth (w + 1) rs0 <= 256.
  Hypothesis LRV : length rv = 156%nat.
  Variable PRV : Z -> Prop.
  Hypothesis HPRV : forall w, minW <= w <= maxW -> PRV (rv_idx cons w).
  Hypothesis HRVR : forall w, minW <= w <= maxW -> 0 <= Znth (rv_idx cons w) rv < 2^32.
  Hypothesis RSA0 : u32arr asegs m0 (WK + 676) (map (Z_to_bv 64) rs0).
  Hypothesis RVA0 : rv_atA m0 WK rv PRV.
  Notation INV m1 dt := (x2fA_inv m0 m1 SPA DT WK T nbb maxW minB scl js jt sorted ncells dt).
  Notation LV2W := [(DT + 4, DT + 4 + 4 * Z.of_nat ncells); (SPA + 616, SPA + 704)].
  Notation L2X m := (rw_cells asegs m (SPA + 568) [C8 (Z_to_bv 64 (cons + nbb)); C8 (Z_to_bv 64 (WK + 52 * cons))]).

  Notation L2SW := [(DT + 4, DT + 4 + 4 * Z.of_nat ncells); (SPA + 296, SPA + 568); (SPA + 616, SPA + 704)].

  Lemma l2sA : forall dt m1 r jw jsp (w0 w1 w2 w3 w4 w5 w6 w7 w8 w9 w10 w11 w12 w13 w14 w15 w16 w17 w18 w19 w20 w21 w22 w23 w24
                                        w25 w26 w27 w28 w29 w30 w32 w33 : word)
      (x1 x5 x6 x7 x10 x11 x12 x13 x14 x15 x16 x17 x19 x20 x21 x22 x23 x25 x27 x28 x29 x30 x31 : word),
    level2_weights (Z.to_nat (maxW + 1)) dt st minW (maxW + 1) T cons rv sorted rs0 nbb sym1 = Ok r ->
    minW < maxW + 1 ->
    INV m1 dt -> L2X m1 -> rw_cells asegs m1 (SPA + 152) [C8 (Z_to_bv 64 minW)] ->
    rw_cells asegs m1 (SPA + 296) [C8 w0; C8 w1; C8 w2; C8 w3; C8 w4; C8 w5; C8 w6; C8 w7; C8 w8; C8 w9; C8 w10; C8 w11; C8 w12; C8 w13; C8 w14; C8 w15; C8 w16; C8 w17; C8 w18; C8 w19; C8 w20; C8 w21; C8 w22; C8 w23; C8 w24; C8 w25; C8 w26; C8 w27; C8 w28; C8 w29; C8 w30; C8 (Z_to_bv 64 (DT + 4 + 4 * st)); C8 w32; C8 w33] ->
    rw_cells asegs m1 (SPA + 616) [CB 8 jw] -> rw_cells asegs m1 (SPA + 624) [CB 80 jsp] ->
    (forall m2 dt' jw' jsp' (y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23 y25 y26 y27 y28 y29 y30 y31 : word),
       r = dt' -> INV m2 dt' -> x2l2frA m2 SPA DT st sym1 -> L2X m2 ->
       rw_cells asegs m2 (SPA + 616) [CB 8 jw'] -> rw_cells asegs m2 (SPA + 624) [CB 80 jsp'] ->
       munch L2SW m1 m2 -> wmono asegs m1 m2 ->
       evtF asegs RNG Q (x2gennA SP SPA gp tp F fc m2 y1 y5 y6 y7 y10 y11 y12 y13 y14 y15 y16 y17 y18 y19 y20 y21 y22 y23
                           y25 y26 y27 y28 y29 y30 y31)) ->
    evtF asegs RNG Q
      (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) x10 x11 x12 x13 x14 x15 x16 x17
               (Z_to_bv 64 (4 * st)) x19 x20 x21 x22 x23 (Z_to_bv 64 2147450880) x25 (Z_to_bv 64 sym1) x27 x28 x29 x30 x31)
